INSERT OR IGNORE INTO activity_versions(activity_id,version,title,description,category_id,heat,experimentation,energy,duration_minutes,metadata_json,status,pack_id,public_preview) VALUES
  ('uninterrupted-attention',1,'Ten minutes of undivided attention','Phones face down, timer on. Spend ten minutes noticing each other out loud and saying what you notice.','connection',0,0,0,10,'{"tags":["attention","quiet"],"environments":["home","hotel","getaway","private-other"],"supplies":["timer"],"preparation":[],"accessibility":["Speak, write or sign your answers.","Eyes-closed version works too."],"safetyFlags":[],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up"]}','published',NULL,0),
  ('compliments',1,'Compliments, on the house','Take turns sharing something you appreciate about each other. Passing is always welcome.','connection',0,0,0,5,'{"tags":["conversation"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Say it, write it, or sign it."],"safetyFlags":[],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up","reconnect"]}','published',NULL,1),
  ('appreciation-inventory',1,'The appreciation inventory','Name three small things from the last week that made the week better. No fixing, no follow-up debate.','connection',0,0,0,10,'{"tags":["gratitude"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Works completely spoken, with no eye contact required."],"safetyFlags":[],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up","reconnect"]}','published',NULL,0),
  ('one-bold-question',1,'One bold question each','Each of you asks the other one question you have been too polite to ask. Either of you may pass, and nothing needs a follow-up.','connection',1,1,0,15,'{"tags":["conversation","nerve"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Write the question down if saying it out loud is hard."],"safetyFlags":["A pass is a complete answer."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','published',NULL,0),
  ('the-honest-answer',1,'The honest answer hour','Trade one question at a time and answer as honestly as you feel like. Skipping is allowed and is not a loss.','connection',1,1,0,30,'{"tags":["honesty"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Answer in writing and hand the page over."],"safetyFlags":["Stop the game at any point without explaining why."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','published',NULL,0),
  ('the-ten-year-postcard',1,'The ten-year postcard','Write each other a two-line postcard from ten years in the future. Read them out loud and laugh at the logistics.','connection',0,1,0,15,'{"tags":["future","writing"],"environments":["home","hotel","getaway","private-other"],"supplies":["pen-paper"],"preparation":[],"accessibility":["Dictate it and let the other person write it down."],"safetyFlags":[],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up"]}','published',NULL,0),
  ('say-it-in-writing',1,'Say it in writing','Write a note you would never say out loud, then decide together whether to read it now, later, or never.','connection',1,0,0,10,'{"tags":["writing","nerve"],"environments":["home","hotel","getaway","private-other"],"supplies":["pen-paper"],"preparation":[],"accessibility":["Typing on a phone counts as writing."],"safetyFlags":["You decide together whether a note is read at all."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','published',NULL,0),
  ('playlist',1,'Set the soundtrack','Pick one song each and make a tiny soundtrack for the evening.','playful',0,0,0,5,'{"tags":["atmosphere"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Lyrics or a quiet shared pause work too."],"safetyFlags":[],"requiredOptIns":[],"incompatibleWith":[],"phases":["setup"]}','published',NULL,1),
  ('two-truths-one-flirt',1,'Two truths and one flirt','Three statements each, only one of them flirtatious. Guess which, then swap roles and keep score badly.','playful',1,1,0,15,'{"tags":["game"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Write the three statements instead of saying them."],"safetyFlags":[],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up"]}','published',NULL,0),
  ('the-coin-says-so',1,'The coin says so','Each of you names two things you would genuinely enjoy tonight. A coin picks one pair. Nothing is binding after the coin lands.','playful',1,1,0,20,'{"tags":["chance"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Use any random picker you like, including a shuffled list."],"safetyFlags":["The coin chooses, you two still decide."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','published',NULL,0),
  ('worst-idea-contest',1,'The worst idea contest','Take turns pitching increasingly terrible date ideas. Points for drama, not plausibility.','playful',1,2,1,15,'{"tags":["comedy"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Pitch by gesture, drawing or text message."],"safetyFlags":[],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up"]}','published',NULL,0),
  ('free-pass-tokens',1,'Two free passes each','Everyone starts with two paper passes. Spend one to skip anything at all, no reason required, and trade the rest later.','playful',1,1,0,20,'{"tags":["boundaries","game"],"environments":["home","hotel","getaway","private-other"],"supplies":["pen-paper"],"preparation":["Tear two paper passes each."],"accessibility":["Say \"pass\" instead of using paper."],"safetyFlags":["Using a pass never needs an explanation."],"requiredOptIns":[],"incompatibleWith":[],"phases":["setup","main"]}','published',NULL,0),
  ('the-mystery-envelope',1,'The mystery envelope','Each of you writes two ideas you would both enjoy, swaps envelopes and draws one. Talking about it is the whole game.','playful',2,2,0,20,'{"tags":["chance","writing"],"environments":["home","hotel","getaway","private-other"],"supplies":["pen-paper"],"preparation":[],"accessibility":["Dictate your ideas to the other person to write."],"safetyFlags":["A drawn idea is a topic, not an instruction."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','published',NULL,0),
  ('twenty-questions-flirty',1,'Twenty questions, badly','One of you thinks of something flirtatious. The other has twenty yes-or-no questions and no talent for them.','playful',1,1,0,20,'{"tags":["game"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Type the questions if speaking is tiring."],"safetyFlags":[],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up"]}','published',NULL,0),
  ('change-the-lighting',1,'Change the lighting','Kill the overhead light and light the room with whatever you already own. Compare two versions until it feels right.','atmosphere',0,0,0,5,'{"tags":["setting"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Bright-light and low-light variants both count."],"safetyFlags":[],"requiredOptIns":[],"incompatibleWith":[],"phases":["setup"]}','published',NULL,0),
  ('phones-in-the-drawer',1,'Phones in the drawer','Both phones go in a drawer for twenty minutes. The first person to check loses an argument of the other person''s choosing.','atmosphere',0,0,0,20,'{"tags":["attention"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Keep a phone if it is needed for caregiving or health."],"safetyFlags":["Caregiving needs beat any game rule."],"requiredOptIns":[],"incompatibleWith":[],"phases":["setup"]}','published',NULL,0),
  ('midnight-snack-plate',1,'The midnight snack plate','Build one ridiculous shared plate from whatever is in the kitchen and eat it somewhere you normally would not.','atmosphere',0,1,0,15,'{"tags":["food"],"environments":["home","hotel","getaway","private-other"],"supplies":["snack"],"preparation":[],"accessibility":["Seated floor picnic counts."],"safetyFlags":["Check ingredients for allergies first."],"requiredOptIns":[],"incompatibleWith":[],"phases":["setup"]}','published',NULL,0),
  ('the-arrival-ritual',1,'Invent an arrival ritual','Pick a small, repeatable thing you do when one of you comes home. Practise it twice and commit to it badly.','atmosphere',1,1,0,10,'{"tags":["ritual"],"environments":["home","hotel","private-other"],"supplies":[],"preparation":[],"accessibility":["A ritual can be a phrase, a sign or a song."],"safetyFlags":[],"requiredOptIns":[],"incompatibleWith":[],"phases":["setup"]}','published',NULL,0),
  ('set-the-scene-in-five',1,'Set the scene in five minutes','Five minutes, no shopping: change three things about the room so it stops looking like a Tuesday.','atmosphere',0,1,1,5,'{"tags":["setting"],"environments":["home","hotel","getaway","private-other"],"supplies":["timer"],"preparation":[],"accessibility":["Delegate the physical parts; choosing counts."],"safetyFlags":[],"requiredOptIns":[],"incompatibleWith":[],"phases":["setup"]}','published',NULL,0),
  ('hotel-room-ritual',1,'The hotel room ritual','Away for the night? Unpack nothing, pour one drink each and invent a rule for the room that only applies tonight.','atmosphere',1,1,0,15,'{"tags":["travel"],"environments":["hotel","getaway"],"supplies":[],"preparation":[],"accessibility":["Bring-your-own-drinks version works identically."],"safetyFlags":["A non-alcoholic option is always on the menu."],"requiredOptIns":[],"incompatibleWith":[],"phases":["setup"]}','published',NULL,0),
  ('slow-dance',1,'The living-room slow dance','Choose a song and invite a dance. Seated movement or simply listening together works beautifully.','movement',0,0,1,5,'{"tags":["music"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":["Clear a comfortable space."],"accessibility":["Seated movement or listening together."],"safetyFlags":["Ask before touch."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','published',NULL,1),
  ('kitchen-sway',1,'Kitchen sway','One song, one small kitchen, no choreography. Bonus point for finishing a drink you forgot you were holding.','movement',0,0,1,10,'{"tags":["music"],"environments":["home","hotel","private-other"],"supplies":[],"preparation":[],"accessibility":["Hold a counter or chair for balance."],"safetyFlags":["Watch hot surfaces and open drawers."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','published',NULL,0),
  ('the-two-song-stretch',1,'The two-song stretch','Two slow songs of stretching next to each other. No goals, no fitness talk, no counting.','movement',0,1,1,10,'{"tags":["body"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Every movement has a seated or in-bed version."],"safetyFlags":["Stop at any twinge; nothing here needs pushing."],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up"]}','published',NULL,0),
  ('hallway-runway',1,'The hallway runway','Walk the length of the hall like the evening depends on it. Score out of ten with complete dishonesty.','movement',1,1,1,10,'{"tags":["silly"],"environments":["home","hotel","private-other"],"supplies":[],"preparation":[],"accessibility":["Wheel, roll, shuffle or sit it out and judge fiercely."],"safetyFlags":[],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up"]}','published',NULL,0),
  ('eleven-minute-shuffle',1,'The eleven-minute shuffle','One playlist, eleven minutes, no sitting down. The only rule is that nobody explains what they are doing.','movement',1,1,2,15,'{"tags":["music","silly"],"environments":["home","hotel","getaway","private-other"],"supplies":["phone-or-speaker"],"preparation":[],"accessibility":["Upper-body-only and seated versions are legitimate."],"safetyFlags":[],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up"]}','published',NULL,0),
  ('hand-massage',1,'The over-generous hand massage','Two minutes per hand, entirely too much care. Ask first, and say when you have had enough.','touch',1,1,0,10,'{"tags":["care"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Lotion is optional; pressure is adjustable."],"safetyFlags":["Ask before touch.","Stop on request without negotiating."],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up"]}','published',NULL,0),
  ('the-long-hug',1,'The unreasonably long hug','One hug, held long past the polite point, with permission to end it whenever either of you likes.','touch',0,0,0,5,'{"tags":["closeness"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Seated, side-by-side, or a hand held for the same length of time."],"safetyFlags":["Ask before touch.","Either person can end it instantly."],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up","reconnect"]}','published',NULL,0),
  ('shoulder-and-scalp',1,'Shoulders first, questions later','Five minutes of shoulder attention for whoever volunteers. Blanket rules and no surprises.','touch',1,1,0,10,'{"tags":["care"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Over clothes only, unless you both agree otherwise."],"safetyFlags":["Ask before touch.","Say where is off-limits before starting."],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up"]}','published',NULL,0),
  ('blanket-burrito',1,'The blanket burrito','One of you gets wrapped up like a very content burrito. The other is in charge of snacks and the remote.','touch',0,0,0,10,'{"tags":["cozy"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["No wrapping needed; a weighted blanket works."],"safetyFlags":["Never cover the face or restrict breathing."],"requiredOptIns":[],"incompatibleWith":[],"phases":["reconnect"]}','published',NULL,0),
  ('trace-a-line',1,'Trace a line','Ask first, then trace one slow line down the other person''s forearm and stop. That is the whole idea.','touch',2,1,0,10,'{"tags":["attention"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Use a fingertip, a feather, or nothing at all."],"safetyFlags":["Ask before touch.","Only where you have both agreed."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','published',NULL,0),
  ('face-hold',1,'The face hold','Hold each other''s face for twenty seconds and try not to laugh. It is harder than it sounds.','touch',1,1,0,5,'{"tags":["closeness"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Forehead touch, a hand hold or a long look all count."],"safetyFlags":["Ask before touch."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','published',NULL,0),
  ('blind-taste-test',1,'The blind taste test','Three small things from the kitchen, eyes closed, described out loud before guessing. Accuracy is not the point.','senses',1,2,0,15,'{"tags":["taste"],"environments":["home","hotel","getaway","private-other"],"supplies":["snack"],"preparation":["Prepare three small, safe tastes."],"accessibility":["The nose-hold version is optional, never mandatory."],"safetyFlags":["Check allergies before anyone tastes anything."],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up"]}','published',NULL,0),
  ('the-scent-memory',1,'The scent memory','Find three things in the house that smell like something. Take turns saying where they take you.','senses',1,2,0,10,'{"tags":["memory"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Describe in words, signs or pictures."],"safetyFlags":["Skip anything that brings back a bad memory."],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up"]}','published',NULL,0),
  ('temperature-play',1,'Cool glass, warm arm','A cold glass against a warm forearm, a warm hand against a cold one. Ask first, and announce every move.','senses',2,1,0,15,'{"tags":["temperature"],"environments":["home","hotel","getaway","private-other"],"supplies":["ice"],"preparation":[],"accessibility":["No skin contact needed; hold the glass just above the skin."],"safetyFlags":["Ask before touch.","Never place ice directly on skin."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','published',NULL,0),
  ('low-light-silhouette',1,'Low-light silhouette','One small light, one doorway, two silhouettes. Take a terrible photo on purpose and never show anyone.','senses',2,1,0,15,'{"tags":["light","silly"],"environments":["home","hotel","private-other"],"supplies":["phone-or-speaker"],"preparation":[],"accessibility":["Photos are optional; describing the shapes is enough."],"safetyFlags":["Nobody photographs anyone without asking."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','published',NULL,0),
  ('the-sound-map',1,'The sound map','Two minutes of listening with your eyes closed, then describe the room purely by its noises.','senses',1,1,0,15,'{"tags":["sound"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Hearing aids, loops and captions welcome; the map can be drawn."],"safetyFlags":[],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up"]}','published',NULL,0),
  ('the-alter-ego-intro',1,'The alter-ego introduction','Invent a stranger with an absurd name and a worse accent, then introduce yourselves to each other as them.','fantasy',2,2,1,20,'{"tags":["role-play","comedy"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Any accent, any language, any volume."],"safetyFlags":["Step out of character whenever you like; the game ends there."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','published',NULL,0),
  ('the-imaginary-getaway',1,'The imaginary getaway','Plan a two-night trip you will not take: where you go, what you eat, what you refuse to do. Be unreasonably specific.','fantasy',1,2,0,15,'{"tags":["travel"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Everything in this trip is free and requires no travel."],"safetyFlags":[],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up"]}','published',NULL,0),
  ('scene-in-three-sentences',1,'Scene in three sentences','Each of you writes a three-sentence scene with the same two characters in it. Read them back to back and pick a favourite.','fantasy',2,2,0,20,'{"tags":["writing","role-play"],"environments":["home","hotel","getaway","private-other"],"supplies":["pen-paper"],"preparation":[],"accessibility":["Speak the scene instead of writing it."],"safetyFlags":["Reading a scene aloud is not agreeing to act it out."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','published',NULL,0),
  ('the-movie-pitch',1,'Pitch the movie of the evening','Give tonight a title, a tagline and a terrible sequel. Whoever gets the other person laughing first wins the title.','fantasy',1,2,0,15,'{"tags":["comedy"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Sign, type or draw the poster instead."],"safetyFlags":[],"requiredOptIns":[],"incompatibleWith":[],"phases":["warm-up"]}','published',NULL,0),
  ('future-flirt',1,'Flirt with the future','Describe one thing you want more of in the next three months and one thing you want to try once. Keep it specific.','fantasy',1,1,0,10,'{"tags":["future","talk"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Write it and hand it over instead."],"safetyFlags":["Asking is not agreement; either of you can leave it there."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','published',NULL,0),
  ('one-thing-that-worked',1,'One thing that worked','Before anyone moves, name one thing from the evening that worked and one thing to do differently next time.','reconnect',0,0,0,5,'{"tags":["debrief"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Say it now or send it tomorrow; both count."],"safetyFlags":[],"requiredOptIns":[],"incompatibleWith":[],"phases":["reconnect"]}','published',NULL,0),
  ('water-and-blanket',1,'Water and a blanket','Fetch the other person water and the blanket with the good texture. Absolutely no post-mortem until morning.','reconnect',0,0,0,5,'{"tags":["care"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Whoever is more able does the fetching; nothing is owed afterwards."],"safetyFlags":[],"requiredOptIns":[],"incompatibleWith":[],"phases":["reconnect"]}','published',NULL,0),
  ('the-goodnight-sentence',1,'The goodnight sentence','Each of you gets one sentence to end the evening. It does not have to be romantic, it just has to be honest.','reconnect',0,0,0,5,'{"tags":["closing"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Text it from the next room."],"safetyFlags":[],"requiredOptIns":[],"incompatibleWith":[],"phases":["reconnect"]}','published',NULL,0),
  ('draft-blindfold-trust',1,'Blindfold trust sequence','A short, fully narrated sequence with a sleep mask, agreed gestures and a stop word before anything begins.','touch',3,2,1,20,'{"tags":["senses","trust"],"environments":["home","hotel","getaway","private-other"],"supplies":["scarf"],"preparation":["Agree the stop word and gestures first."],"accessibility":["Fully guided by voice; seated version available."],"safetyFlags":["Ask before touch.","Remove the mask at any sign of discomfort."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','draft',NULL,0),
  ('draft-whispered-inventory',1,'The whispered inventory','Trade a slow, whispered list of things you would like, with the explicit understanding that nothing is a request.','fantasy',3,2,0,20,'{"tags":["talk","nerve"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":[],"accessibility":["Write the list and let the other read it silently."],"safetyFlags":["A list is not a promise, a request or permission."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','draft',NULL,0),
  ('draft-silk-and-ice',1,'Silk and ice','Two textures, one arm, several announcements. A sensory experiment with a stop word and no surprises.','senses',3,2,0,20,'{"tags":["temperature"],"environments":["home","hotel","getaway","private-other"],"supplies":["ice","scarf"],"preparation":[],"accessibility":["No-skin-contact version keeps the textures on the table."],"safetyFlags":["Ask before touch.","Never place ice directly on skin."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','draft',NULL,0),
  ('draft-midnight-role-call',1,'The midnight role call','Invent a character who is definitely not you, agree a scene and a way out, then talk in character for ten minutes.','fantasy',3,2,1,30,'{"tags":["role-play"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":["Agree the scene and the exit line."],"accessibility":["Text-only version works."],"safetyFlags":["An exit line ends the scene immediately, every time."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','draft',NULL,0),
  ('draft-slow-burn-sequence',1,'The slow-burn sequence','A three-step sequence written by both of you in advance, with every step individually opt-in and skippable.','touch',3,2,1,30,'{"tags":["sequence"],"environments":["home","hotel","getaway","private-other"],"supplies":[],"preparation":["Write three steps; both initial each one."],"accessibility":["Any step can be replaced by a seated alternative."],"safetyFlags":["Ask before touch.","Skipping a step is not a failure."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','draft',NULL,0),
  ('draft-secret-menu-card',1,'The secret menu card','A private card of things you are curious about, sealed and opened only if both of you choose to.','fantasy',3,2,0,20,'{"tags":["writing"],"environments":["home","hotel","getaway","private-other"],"supplies":["pen-paper"],"preparation":[],"accessibility":["Dictate into a shared document instead."],"safetyFlags":["Opening the card requires both of you, every time."],"requiredOptIns":[],"incompatibleWith":[],"phases":["main"]}','draft',NULL,0);

